  "measure_id": "MEAS-A2846196",
  "restatements": [
    {
      "clause_id": "§1",
      "text": "Increases the state minimum wage to $17.00 per hour beginning January 1, 2028."
    }
  ],
  "findings": [
    {
      "id": "f1",
      "clause_id": "§1",
      "concern_id": "C11",
      "effect": "advances",
      "direction": null,
      "quote": "the state minimum wage increases to $17.00 per hour.",
      "mechanism": "Raises the base hourly pay that employers are required to provide to workers from the current $15.00 to $17.00.",
      "certainty": "stated"
    },
    {
      "id": "f2",
      "clause_id": "§1",
      "concern_id": "C08",
      "effect": "costs",
      "direction": null,
      "quote": "the state minimum wage increases to $17.00 per hour.",
      "mechanism": "Requires employers to pay a higher base wage, increasing their labor and payroll expenses.",
      "certainty": "stated"
    }
  ],
  "analysis": [
    {
      "clause_id": "§1",
      "question_id": "Q1",
      "answer": "Current law sets the state minimum wage at $15.00 per hour. The measure increases this rate to $17.00 per hour effective January 1, 2028.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q2",
      "answer": "Direct costs include higher payroll expenses for private businesses and government employers paying workers below $17.00 per hour, along with correspondingly higher payroll taxes. Opportunity costs may include reduced hiring or fewer hours offered to entry-level workers.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q3",
      "answer": "Workers currently earning below $17.00 per hour benefit from higher hourly wages. Employers bear the direct cost of the wage increase. Consumers may ultimately pay more if businesses raise the prices of goods and services to offset their higher labor costs.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q4",
      "answer": "Employers may respond to the increased labor costs by raising prices, reducing employee hours, tightening hiring standards, or investing in automation to replace some entry-level tasks.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q5",
      "answer": "The measure addresses the purchasing power of low-wage workers by directly raising the legal wage floor. This mechanism may create a shortage of entry-level jobs if employers reduce headcount or hours to offset the higher per-hour costs.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q7",
      "answer": "The effect on jobs is disputed. Some researchers find that minimum wage increases reduce employment or total hours for low-wage and youth workers. Other researchers find negligible negative employment effects and note that such increases substantially raise the total earnings of low-wage workers.",
      "disputed": true
    }
  ],
